(function(root){
 'use strict';
 root.SEASON_FEATURES={
  0:{foodId:'yanshi-fresh-yintiao',line:'寒到深处，地下还藏着清脆。',intro:'冬天也能吃得清亮。细白银条在热水里煮熟，沥干后拌一点姜醋；一盘热菜旁边，正好留一口脆。',reason:'像一把细白小枝，吃的是地下嫩茎。小寒前后的新挖银条，焯熟拌姜醋，清脆里带淡甜。'},
  1:{foodId:'bishan-ercai',line:'小芽抱成团，寒冬也有嫩意。',intro:'儿菜的小芽紧紧围着主茎，掰下来就有一盘。清水煮透，蘸料另放，让冬菜的微苦与回甜都露个面。',reason:'一颗菜抱着一圈小芽，掰开就是一口一口。白水煮透，尝芽体的柔脆，再蘸一点辣。'},
  2:{foodId:'jiaozhou-kailing-suo',line:'河口冰开，鲜味先到。',intro:'春天先从河口捎来消息。赶开凌梭的短季，也看看冬菜最后的嫩；有的适合清蒸，有的只需一锅清水。',reason:'“开凌”说的是冰解开春的短季。蒸熟后拨开银灰鱼皮，里面是细白、润泽的鱼肉。'},
  3:{foodId:'wuding-jinquehua',line:'雨落花开，春天可以炒着吃。',intro:'雨水渐尽，三月的武定有金黄小花可尝。把明确供食用的鲜花炒进鸡蛋，花瓣柔软，尾味留一点春天的微苦。',reason:'花形像小雀，鲜黄花瓣也能入菜。三月鲜花配鸡蛋炒熟，柔软里带清香，尾味微苦。'},
  4:{foodId:'yongsheng-fresh-kapok',line:'木棉开红了，锅里却是另一副模样。',intro:'惊蛰的鲜味不只在嫩叶里。木棉开过高枝，食用花蕊便有了去处；先处理妥当，再让豆豉与蒜苗把香气炒出来。',reason:'红木棉入菜，取的是细束花蕊。焯熟漂洗后炒豆豉蒜苗，滑脆里还留着一点微涩。'},
  5:{foodId:'fengqing-xinhua-walnut-flowers',line:'果仁还早，先吃树上的花。',intro:'昼夜平分，核桃树垂下细长雄花。三月中旬至四月中旬的鲜花短季，焯泡去苦后炒腊肉，春鲜与冬藏正好碰头。',reason:'核桃还没结仁，雄花已成一串春菜。取花茎焯泡去苦，再和腊肉炒出一口脆爽。'},
  6:{foodId:'eryuan-haicaihua',line:'花浮水面，鲜味藏在长茎里。',intro:'春水上的白花很好看，筷子夹起的嫩茎也值得细尝。海菜花熟后滑嫩而略脆，和鸡蛋快炒，清鲜便有了着落。',reason:'水上开着白花，餐桌上多吃嫩茎与花葶。和鸡蛋炒熟，先觉滑嫩，咬下去又有轻脆。'},
  7:{foodId:'cinenya',line:'趁嫩叶还没舒展，接住春天的苦香。',intro:'春雨过后，山野嫩芽正赶着长。只选身份明确的食用刺嫩芽，去老苞、焯熟，再决定蘸酱还是炒蛋。',reason:'嫩叶尚未展开，芽体厚实又带一点苦。去掉硬苞焯熟，蘸酱吃，最容易认识它的肉质口感。'},
  8:{foodId:'jianshui-caoya',line:'水田里抽出一口乳白的鲜。',intro:'初夏的水田送来细长白尖。建水草芽看着像小象牙，入锅后柔脆清甜；切嫩段炒鸡丝，别让粗老部分抢了口感。',reason:'像小象牙的乳白嫩尖，是香蒲类植物的嫩根状茎。炒鸡丝，柔脆多水，清甜很轻。'},
  9:{foodId:'shanzhou-green-wheat-nianzhuan',line:'麦子还青，已经值得开火。',intro:'等不到麦粒全黄，陕州人先尝青麦的鲜。小满前后的碾转留着谷物香，和鸡蛋炒成一盘，短碎条仍有一点咬劲。',reason:'青麦仁趁饱满碾成短碎条，叫作碾转。和鸡蛋炒热，尝新麦的谷物甜与一点嚼劲。'},
  10:{foodId:'tonghai-fresh-sour-quince',line:'把鲜果的酸，慢慢煮进汤里。',intro:'芒种时节，果味也能走进热汤。通海六月成熟的酸木瓜少放几片，和鸡肉慢炖；先从一小口汤，认识它明亮的酸。',reason:'这味木瓜以酸香见长，鲜果少量切片入鸡汤。果片煮软，酸味融进汤里，吃法也换个方向。'},
  11:{foodId:'harbin-fresh-honeyberry',line:'日光最长，果汁也染上深紫。',intro:'六月中下旬，寒地浆果开始熟透。细长蓝靛果皮薄多汁，挑鲜食品种，轻洗后尝几颗；这段鲜果季值得温柔对待。',reason:'蓝紫小果细长，轻咬却流出紫红果汁。六月中下旬尝成熟鲜食品种，酸甜都很鲜明。'},
  12:{foodId:'chenghai-baoke',line:'这一盘“米”，带着海风的鲜。',intro:'暑气起来，潮汕薄壳也到了肥美时候。细小贝肉剥成一盘，金不换的香气一入锅，夏天就有了下饭的理由。',reason:'薄壳米是剥出的细小贝肉。七八月肥美时，配金不换炒熟，一粒粒鲜甜、柔嫩带弹。'},
  13:{foodId:'xishuangbanna-wood-milk-fruit',line:'果子挤上树干，盛夏另有酸甜。',intro:'热带的熟果未必都藏在枝叶尽头。木奶果一串串结在枝干上，剥开韧皮，浅色果肉带着充足汁水，酸甜正适合慢尝。',reason:'果实一串串贴着枝干长，剥开是浅色软嫩果肉。七八月成熟，尝一口多汁的酸甜。'},
  14:{foodId:'jitoumi',line:'秋还浅，水乡先剥出一碗鲜。',intro:'暑热尚在，苏州水乡已经惦记新剥鸡头米。先煮一小碗，糖不必多，感受鲜粒表面的滑、咬下去的弹与中心的糯。',reason:'芡实果里手剥出的鲜粒，像小颗白珠。清氽后滑润微弹，中心略糯，和干芡实是两种口感。'},
  15:{foodId:'ganbajun',line:'暑意将退，雨季菌香仍浓。',intro:'夏末的云南，鲜菌仍跟着雨水出现。干巴菌的灰褐分叉藏着浓香，认真清去松针碎屑，再把它炒熟炒透，拌进热饭。',reason:'灰褐菌体层层分叉，炒熟有腌肉似的浓香。雨季鲜菌撕净杂叶，配青椒炒饭，越嚼越有味。'},
  16:{foodId:'huoshan-yanghe',line:'贴地的紫红花苞，藏着温和姜香。',intro:'九月霍山的阳荷嫩苞，紫红苞片一层抱着一层。薄切后与肉片同炒，既留脆意，也把温和辛香带进这一餐。',reason:'姜科植物贴地长出的紫红嫩苞，层层苞片抱紧。切片炒肉，脆口里有比生姜柔和的辛香。'},
  17:{foodId:'bayuegua',line:'山果自己开了口，秋天便露出甜。',intro:'昼夜平分，山果也到了柔软的时候。八月瓜熟了会自然裂口，舀出白色果肉慢慢吃，别让满满黑籽打断寻味的耐心。',reason:'熟果会自然裂开，露出黑籽密布的白色果肉。舀一口软滑的甜，慢慢吐籽，尝它的成熟。'},
  18:{foodId:'ximeng-bamboo-worm',line:'竹节里的秋味，熟后才露出香。',intro:'凉露落下，西盟鲜竹虫仍在短季里。愿意尝这一味的人，可以先从一小份开始：充分熟制，再煎到外层干香。',reason:'竹节里长大的地方鲜味，九月中旬至十月底有鲜货。充分做熟再煎香，外层干香、内里柔软。'},
  19:{foodId:'xunyang-guizao',line:'弯弯的小枝，也能藏住深秋的甜。',intro:'霜降之后，旬阳拐枣渐熟。看着像枝条，吃的却是膨大的肉质果梗；去掉硬果，鲜尝或打成清饮，都能认识这口甜。',reason:'弯弯曲曲像小枝，甜味藏在膨大的肉质果梗。霜降后成熟，去掉硬果，慢慢嚼或打成清饮。'},
  20:{foodId:'helan-luosicai',line:'山收秋色，海藏鲜味，初冬的餐桌渐暖。',intro:'立冬时节，田间有新挖的根茎，枝头留着晚熟的果实，沿海也有当令的鲜味。循着各地的收获，尝一尝初冬的清甜与鲜香。',reason:'乳白块茎一节节盘成小螺旋，别名草石蚕。十一月的鲜货洗净煮熟，清炒尝它的脆嫩。'},
  21:{foodId:'xiaolan-shiju-huaban',line:'热汤开了，添一把晚秋的花。',intro:'小雪前后，小榄食用菊到了凉季赏味时。把鲜花瓣放进清鸡汤，短时加热到熟，花香轻一点，汤也留得清。',reason:'食用菊的鲜花瓣，十一月下旬正好入汤。临起锅前煮熟，柔嫩清香，和鸡肉相互陪衬。'},
  22:{foodId:'baoshan-liangcui-emblica',line:'深冬的一口酸，后面还跟着甘。',intro:'十二月中下旬，保山晚熟“亮脆”余甘子才进入成熟期。先去核尝一小片，再喝口清水，让酸涩与回甘慢慢排开。',reason:'保山晚熟“亮脆”，十二月中下旬才熟。浅绿果肉紧实，先酸涩，细嚼后回甘，值得慢尝。'},
  23:{foodId:'shantou-haojiang-liqian-dongjingwan',line:'长夜里，等一锅小丸慢慢透亮。',intro:'冬至的甜，可以从潮汕的一碗糖水开始。里前东京丸先煮透，再放姜薯薄片与红糖；小丸软糯，把这一晚吃得暖一些。',reason:'东京薯磨粉、摇丸、晒干，成了形似西米的小丸。冬至配姜薯红糖煮透，软糯的甜留给长夜。'}
 };
})(typeof window==='undefined'?globalThis:window);
